// ---------- Bloque 1: leer datos ----------
const { config: c, entrada } = $input.first().json;
const origen = entrada && entrada.body && entrada.body.evento === 'apartado.vencido'
  ? 'evento' : 'calendario';

// ---------- Bloque 2: fijar "hoy" una sola vez (Europe/Madrid, AAAA-MM-DD) ----------
// hoy_prueba solo existe en datos fijados a mano en el Schedule Trigger: ese nodo no recibe entrada externa.
const esFecha = v => typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v);
const hoy = (origen === 'calendario' && esFecha(entrada && entrada.hoy_prueba))
  ? entrada.hoy_prueba
  : new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Madrid' }).format(new Date());

// ---------- Bloque 3: comprobar ----------
for (const k of ['API_BASE_URL', 'CORREO_MARISA', 'CORREO_REMITENTE']) {
  if (typeof c[k] !== 'string' || c[k].trim() === '') throw new Error(`Falta configuración: ${k}`);
}
if (origen === 'evento') {
  const d = entrada.body.datos;
  if (!d || typeof d.apartado !== 'object' || typeof d.vale !== 'object') {
    throw new Error('Evento de vencimiento sin apartado o vale');
  }
}

return [{ json: { config: c, origen, hoy, datos: origen === 'evento' ? entrada.body.datos : null } }];

// ---------- Bloque 1: leer datos ----------
const { hoy, config } = $('Preparar contexto').first().json;
const resp = $input.first().json;
if (resp.statusCode !== 200 || !Array.isArray(resp.body)) {
  throw new Error('La API no devolvió la lista de apartados activos');
}

// ---------- Bloque 2: días entre fechas de calendario (sin horas) ----------
const esFecha = v => typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v);
const aUTC = f => { const [y, m, d] = f.split('-').map(Number); return Date.UTC(y, m - 1, d); };
const dias = (desde, hasta) => Math.round((aUTC(hasta) - aUTC(desde)) / 86400000);

// ---------- Bloque 3: clasificar ----------
const salida = [];
for (const a of resp.body) {
  if (a.estado !== 'activo') continue;
  if (!Number.isInteger(a.id) || !esFecha(a.fecha_limite)) {
    throw new Error('Apartado activo sin id o fecha límite válidos');
  }
  const restantes = dias(hoy, a.fecha_limite);
  let accion = null, hito = null;
  if (restantes < 0) accion = 'vencer';
  else if (restantes === 7 || restantes === 1) { accion = 'recordatorio'; hito = restantes; }
  if (accion) {
    salida.push({ json: { accion, hito, dias_restantes: restantes, hoy, config, apartado: a } });
  }
}
return salida;

// ---------- Bloque 1: ayudas de formato (solo presentación, sin cálculos) ----------
const euros = v => `${Number(v).toFixed(2).replace('.', ',')} €`;
const fechaEs = f => f.split('-').reverse().join('/');
const esTexto = v => typeof v === 'string' && v.trim() !== '';

// ---------- Bloque 2: un documento por apartado ----------
const salida = [];
for (const it of $input.all()) {
  const { apartado: a, hito, config: c } = it.json;

  if (!esTexto(c.CORREO_REMITENTE) || !esTexto(c.CORREO_MARISA)) throw new Error('Falta configuración de correo');
  if (!Number.isInteger(a.id) || !esTexto(a.cliente) || !esTexto(a.producto)) throw new Error('Faltan datos del apartado');
  if (![7, 1].includes(hito)) throw new Error('Hito de recordatorio inesperado');
  if (!Number.isFinite(a.abonado) || !Number.isFinite(a.pendiente)) throw new Error('Faltan datos financieros del apartado');

  const cuando = hito === 7 ? 'dentro de 7 días' : 'mañana';
  const talla = esTexto(a.talla) ? ` (talla ${a.talla})` : '';
  const limite = fechaEs(a.fecha_limite);
  const base = `${a.fecha_limite}:${hito}`;

  if (esTexto(a.email)) {
    salida.push({ json: {
      clave: `${a.id}:${base}:email`,
      tipo: 'recordatorio',
      documento: {
        remitente: c.CORREO_REMITENTE,
        destinatario: a.email.trim(),
        asunto: `Tu apartado de ${a.producto} vence ${cuando}`,
        texto: `Hola ${a.cliente},\n\nTe recordamos que tu apartado de ${a.producto}${talla} vence ${cuando}, el ${limite}.\n\nHas abonado ${euros(a.abonado)} y te quedan ${euros(a.pendiente)} por pagar.\n\nPuedes completar el pago hasta el ${limite} incluido. Pasado ese día, el apartado vence y se genera un vale por lo abonado.\n\nZapatería Paso Firme`
      }
    } });
  } else {
    const tel = esTexto(a.telefono) ? ` Teléfono: ${a.telefono}.` : '';
    salida.push({ json: {
      clave: `${a.id}:${base}:marisa`,
      tipo: 'recordatorio_sin_email',
      documento: {
        remitente: c.CORREO_REMITENTE,
        destinatario: c.CORREO_MARISA,
        asunto: `Apartado ${a.id} sin correo: recordatorio sin enviar`,
        texto: `El apartado ${a.id} de ${a.cliente} (${a.producto}${talla}) vence ${cuando}, el ${limite}. Abonado: ${euros(a.abonado)}. Pendiente: ${euros(a.pendiente)}.\n\nNo tiene correo registrado, así que no se ha enviado el recordatorio al cliente. Avísale por otro medio.${tel}`
      }
    } });
  }
}
return salida;

// ---------- Bloque 1: leer datos ----------
const { config } = $('Preparar contexto').first().json;
const salida = [];

for (const it of $input.all()) {
  const r = it.json;
  if (r.statusCode !== 200 || !r.body || typeof r.body !== 'object') {
    throw new Error('No se pudo releer el apartado tras pedir su vencimiento');
  }

  // ---------- Bloque 2: decidir con lo que dice la API ----------
  const { abonos, vale, ...apartado } = r.body;
  if (apartado.estado === 'liquidado') continue;          // otro proceso lo liquidó: no se avisa
  if (apartado.estado === 'activo') {
    throw new Error(`El apartado ${apartado.id} sigue activo tras pedir su vencimiento`);
  }
  if (apartado.estado !== 'vencido' || !vale || typeof vale.codigo !== 'string' || !Number.isFinite(vale.importe)) {
    throw new Error(`El apartado ${apartado.id} está vencido pero la API no devuelve un vale válido`);
  }

  // ---------- Bloque 3: salida normalizada (código e importe del vale tal cual los da la API) ----------
  salida.push({ json: { config, apartado, vale } });
}
return salida;

// ---------- Bloque 1: ayudas (solo formato, sin cálculos) ----------
const euros = v => `${Number(v).toFixed(2).replace('.', ',')} €`;
const fechaEs = f => f.split('-').reverse().join('/');
const esTexto = v => typeof v === 'string' && v.trim() !== '';

// ---------- Bloque 2: un par de avisos por vale ----------
const salida = [];
for (const it of $input.all()) {
  // Calendario trae {config, apartado, vale}; el evento de PF-00 trae {config, datos: {apartado, vale}}
  const c = it.json.config;
  const { apartado: a, vale: v } = it.json.datos ?? it.json;

  if (!esTexto(c.CORREO_REMITENTE) || !esTexto(c.CORREO_MARISA)) throw new Error('Falta configuración de correo');
  if (!a || a.estado !== 'vencido') throw new Error('El apartado no consta como vencido');
  if (!v || !esTexto(v.codigo) || !Number.isFinite(v.importe) || v.apartado_id !== a.id) {
    throw new Error(`Vale ausente o incoherente para el apartado ${a.id}`);
  }

  const talla = esTexto(a.talla) ? `talla ${a.talla}` : 'talla no indicada';
  const base = `vale:${v.codigo}`;

  // Aviso al cliente (solo si tiene correo)
  if (esTexto(a.email)) {
    salida.push({ json: {
      clave: `${base}:cliente`,
      tipo: 'vencimiento_cliente',
      documento: {
        remitente: c.CORREO_REMITENTE,
        destinatario: a.email.trim(),
        asunto: `Tu apartado de ${a.producto} ha vencido: tienes un vale`,
        texto: `Hola ${a.cliente},\n\nTu apartado de ${a.producto} (${talla}) venció el ${fechaEs(a.fecha_limite)} sin completarse el pago.\n\nHemos generado un vale de compra por lo que habías abonado:\n\nCódigo: ${v.codigo}\nImporte: ${euros(v.importe)}\n\nPuedes usarlo en tu próxima compra en la tienda. No se devuelve en efectivo.\n\nZapatería Paso Firme`
      }
    } });
  }

  // Aviso a Marisa (siempre): liberar el par y, si falta correo, avisar al cliente por otro medio
  const sinCorreo = esTexto(a.email) ? '' :
    `\n\nEl cliente no tiene correo registrado: no se le ha enviado el aviso. Comunícale el vale por otro medio.${esTexto(a.telefono) ? ` Teléfono: ${a.telefono}.` : ''}`;
  salida.push({ json: {
    clave: `${base}:marisa`,
    tipo: 'vencimiento_tienda',
    documento: {
      remitente: c.CORREO_REMITENTE,
      destinatario: c.CORREO_MARISA,
      asunto: `Apartado ${a.id} vencido: liberar ${a.producto} (${talla})`,
      texto: `El apartado ${a.id} de ${a.cliente} ha vencido (fecha límite ${fechaEs(a.fecha_limite)}).\n\nPar a liberar: ${a.producto}, ${talla}.\nVale generado por la app: ${v.codigo} por ${euros(v.importe)}.\n\nLa app no modifica el inventario: vuelve a poner el par a la venta.${sinCorreo}`
    }
  } });
}
return salida;

// ---------- Bloque 1: leer datos ----------
const { hoy } = $('Preparar contexto').first().json;
const resp = $input.first().json;
if (resp.statusCode !== 200 || !Array.isArray(resp.body)) {
  throw new Error('La API no devolvió la lista de vales');
}

// ---------- Bloque 2: ventana de 7 días de calendario (hoy incluido) ----------
const aUTC = f => { const [y, m, d] = f.split('-').map(Number); return Date.UTC(y, m - 1, d); };
const desde = new Date(aUTC(hoy) - 7 * 86400000).toISOString().slice(0, 10);

// ---------- Bloque 3: un item por vale reciente ----------
return resp.body
  .filter(v => typeof v.fecha === 'string' && v.fecha >= desde && v.fecha <= hoy && Number.isInteger(v.apartado_id))
  .map(v => ({ json: { vale: v } }));
